柯里化就是将多参函数变成单参函数

```js
// 实现函数柯里化
function currying() {

}

// 测试柯里化函数
const sum = (a, b, c, d) => a + b + c + d;

console.log(currying(sum)(1)(2)(3)(4)); // 10
console.log(currying(sum, 1)(2, 3)(4)); // 10
console.log(currying(sum, 1, 2)(3)(4)); // 10
console.log(currying(sum, 1, 2)(3, 4)); // 1

# 防抖函数

防抖函数

## 封装

```js
// 防抖函数的封装
export default function debounce(func, delay){
  let timer = null
  return function () {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      func.apply()
    }, delay)
  }
}

```

